  const bob=reduce?0:Math.sin(t*.9)*.06;
  const pr=11*S,pc=[CX,CY+9.2*S];const pg=ctx.createRadialGradient(pc[0],pc[1]-pr*.7,pr*.1,pc[0],pc[1],pr);pg.addColorStop(0,rgb(T.planet,neon?.28:.42));pg.addColorStop(1,rgb(T.planet,0));
  ctx.fillStyle=pg;ctx.beginPath();ctx.arc(pc[0],pc[1],pr,0,7);ctx.fill();ctx.strokeStyle=T.planetLine;ctx.lineWidth=1;ctx.beginPath();ctx.arc(pc[0],pc[1],pr,0,7);ctx.stroke();
