async function exportChartImage(chart) {
  if (!chart) return null;
  const copy = chart.cloneNode(true);
  copy.setAttribute("xmlns", "http://www.w3.org/2000/svg");
  copy.setAttribute("width", "288");
  copy.setAttribute("height", "228");
  const selectors = "polygon, line, circle, rect, text";
  const originals = chart.querySelectorAll(selectors);
  copy.querySelectorAll(selectors).forEach((element, index) => {
    const style = getComputedStyle(originals[index]);
    for (const property of ["fill", "stroke", "strokeWidth", "strokeDasharray", "fontFamily", "fontSize", "fontWeight"]) {
      element.style[property] = style[property];
    }
  });
  const image = new Image();
  image.src = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(new XMLSerializer().serializeToString(copy));
  await image.decode();
  return image;
}

