function encodeJpeg(canvas) {
  return new Promise((resolve, reject) => {
    canvas.toBlob((blob) => blob?.type === "image/jpeg" ? resolve(blob) : reject(new Error("결과지 이미지 생성 실패")), "image/jpeg", .94);
  });
}

function fileDataUrl(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = () => reject(reader.error);
    reader.readAsDataURL(file);
  });
}

async function buildPrintExport(report) {
  const result = await renderPrintImage(report);
  const photo = await encodeJpeg(result);
  const sheet = photo;
  const pdf = await printPdf(sheet, result.width, result.height);
  const [photoUrl, sheetUrl, pdfUrl] = await Promise.all([fileDataUrl(photo), fileDataUrl(sheet), fileDataUrl(pdf)]);
  return {
    photoUrl, sheetUrl, pdfUrl,
    photoFile: new File([photo], "siseonsai-result.jpg", { type: "image/jpeg" }),
    pdfFile: new File([pdf], "siseonsai-print-a4.pdf", { type: "application/pdf" }),
  };
}

async function printPdf(jpeg, width, height) {
  // Keep the PDF page inside the printable area of A4 paper at actual size.
  const image = new Uint8Array(await jpeg.arrayBuffer());
  const encoder = new TextEncoder();
  const chunks = [];
  const offsets = [0];
  let length = 0;
  const add = (data) => {
    const bytes = typeof data === "string" ? encoder.encode(data) : data;
    chunks.push(bytes);
    length += bytes.length;
  };
  const object = (...parts) => {
    offsets.push(length);
    add((offsets.length - 1) + " 0 obj\n");
    parts.forEach(add);
    add("\nendobj\n");
  };
  const pageWidth = 210 * 72 / 25.4;
  const pageHeight = 297 * 72 / 25.4;
  const w = printWidthMm * 72 / 25.4;
  const h = w * height / width;
  const placement = `q ${w.toFixed(2)} 0 0 ${h.toFixed(2)} ${((pageWidth - w) / 2).toFixed(2)} ${((pageHeight - h) / 2).toFixed(2)} cm /J Do Q\n`;
  add("%PDF-1.6\n");
  add(new Uint8Array([37, 226, 227, 207, 211, 10]));
  object("<< /Type /Catalog /Pages 2 0 R /ViewerPreferences << /PrintScaling /None >> >>");
  object("<< /Type /Pages /Kids [3 0 R] /Count 1 >>");
  object(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pageWidth.toFixed(2)} ${pageHeight.toFixed(2)}] /Resources << /XObject << /J 4 0 R >> >> /Contents 5 0 R >>`);
  object(`<< /Type /XObject /Subtype /Image /Width ${width} /Height ${height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${image.length} >>\nstream\n`, image, "\nendstream");
  object(`<< /Length ${placement.length} >>\nstream\n`, placement, "endstream");
  const xref = length;
  add(`xref\n0 ${offsets.length}\n0000000000 65535 f \n`);
  offsets.slice(1).forEach((offset) => add(`${String(offset).padStart(10, "0")} 00000 n \n`));
  add(`trailer\n<< /Size ${offsets.length} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`);
  return new Blob(chunks, { type: "application/pdf" });
}

async function preparePrintImage(dialog) {
  if (printExport || printPreparation) return;
  const status = dialog.querySelector(".print-status");
  const actions = dialog.querySelectorAll(".export-actions [data-action]");
  const setDisabled = (disabled) => actions.forEach((action) => {
    if (action.tagName === "BUTTON") action.disabled = disabled;
    else action.setAttribute("aria-disabled", String(disabled));
  });
  setDisabled(true);
  status.textContent = "인쇄와 저장을 준비하고 있어요.";
  const pending = buildPrintExport(dialog.closest(".report"));
  printPreparation = pending;
  try {
    const prepared = await pending;
    if (printPreparation !== pending || !dialog.isConnected) return;
    printSheet.style.setProperty("--print-sheet-width", printWidthMm + "mm");
    printSheet.src = prepared.sheetUrl;
    await printSheet.decode();
    if (printPreparation !== pending || !dialog.isConnected) return;
    printExport = prepared;
    document.body.classList.add("print-ready");
    const preview = dialog.querySelector(".print-preview");
    preview.src = prepared.photoUrl;
    preview.hidden = false;
    dialog.querySelectorAll(".export-actions a").forEach((link) => {
      const printing = ['native-print','download-print-pdf'].includes(link.dataset.action);
      link.href = printing ? prepared.pdfUrl : prepared.photoUrl;
      link.download = (printing ? prepared.pdfFile : prepared.photoFile).name;
    });
    status.textContent = "";
  } catch {
    if (printPreparation === pending) status.textContent = "파일 준비에 실패했어요. 인쇄나 저장을 다시 눌러 주세요.";
  } finally {
    if (printPreparation === pending) {
      printPreparation = null;
      setDisabled(false);
    }
  }
}

function saveExportFile(url, name) {
  const link = document.createElement("a");
  link.href = url;
  link.download = name;
  link.hidden = true;
  document.body.append(link);
  link.click();
  setTimeout(() => link.remove(), 0);
}

function canShareExport(file) {
  try {
    return typeof navigator.share === "function" && navigator.canShare?.({ files: [file] });
  } catch {
    return false;
  }
}

function usePrintExport(event, action, printing) {
  const dialog = action.closest("dialog");
  if (!printExport) {
    event.preventDefault();
    return preparePrintImage(dialog);
  }
  const status = dialog.querySelector(".print-status");
  stopNarration();
  if (action.tagName === "A") {
    const file = printing ? printExport.pdfFile : printExport.photoFile;
    const useSystemMenu = (printing && (appleMobile || inAppBrowser)) || (!printing && appleMobile && inAppBrowser);
    if (useSystemMenu && !action.dataset.shareFallback && canShareExport(file)) {
      event.preventDefault();
      status.textContent = printing ? "기기 메뉴에서 ‘프린트’ 또는 ‘인쇄’를 골라 주세요." : "기기 메뉴에서 ‘이미지 저장’을 골라 주세요.";
      const failed = (error) => {
        if (!action.isConnected || (error.name === "AbortError" && !printing)) return;
        action.dataset.shareFallback = "true";
        status.textContent = printing
          ? "같은 버튼을 다시 누르면 인쇄용 A4 PDF를 내려받아요."
          : "기기 메뉴를 열지 못했어요. 같은 버튼을 다시 누르면 JPG를 내려받아요.";
      };
      try {
        navigator.share({ files: [file] }).catch(failed);
      } catch (error) {
        failed(error);
      }
      return;
    }
    status.textContent = printing
      ? "내려받은 A4 PDF를 열고 100% 또는 실제 크기로 인쇄해 주세요."
      : appleMobile ? "다운로드한 JPG는 아이폰이나 아이패드의 파일 앱에서 확인해 주세요." : "내려받은 파일에서 siseonsai-result.jpg를 확인해 주세요.";
    return;
  }
  if (action.dataset.printFallback) {
    saveExportFile(printExport.pdfUrl, printExport.pdfFile.name);
    status.textContent = "내려받은 A4 PDF를 열고 100% 또는 실제 크기로 인쇄해 주세요.";
    return;
  }
  let opened = false;
  const didOpen = () => { opened = true; };
  window.addEventListener("beforeprint", didOpen, { once: true });
  dialog.close();
  try {
    window.print();
  } catch {
    // The same control offers the prepared PDF if the native print dialog fails.
  } finally {
    setTimeout(() => {
      window.removeEventListener("beforeprint", didOpen);
      if (opened || !action.isConnected || !printExport || dialog.open) return;
      action.dataset.printFallback = "true";
      dialog.showModal();
      status.textContent = "인쇄 창을 열지 못했어요. 같은 버튼을 누르면 A4 PDF를 내려받아요.";
    }, 800);
  }
}

document.addEventListener("click", (event) => {
  const target = event.target.closest("[data-action]");
  if (!target) {
    const card = event.target.closest("[data-practice-card]");
    if (card) openPractice(Number(card.dataset.practiceCard));
    return;
  }
  const { action, role, index, value } = target.dataset;
  queueMicrotask(markNextReady);
  switch (action) {
    case "home": return show('home');
    case "hatch-start": return startEndingEgg();
    case "mission-open": return openMissionTheater();
    case "mission-play": return playMission();
    case "family-results": return openFamilyResults();
    case "mission-pause": return pauseMission();

    case "begin-voice": voiceEnabled ??= true; return beginFreshBook();
    case 'reason-mic': return toggleReasonVoice();
    case 'resume-review': return edit(familySession.role,0);
    case 'station-create': return createStation();
    case 'station-join': return joinStation();
    case 'photo-location':
      narrate('photo-intro');
      app.querySelector('#print-options')?.close();
      app.querySelector('#family-photo-upload')?.scrollIntoView({block:'start',behavior:'smooth'});
      return app.querySelector('[data-family-photo]')?.focus({preventScroll:true});
    case 'station-link-retry': return openStationLink(stationEntryRole);
    case 'station-child-entry':
      if(stationSession || familySession)return;
      event.preventDefault();stationEntryRole='child';history.replaceState(null,'',stationRoleUrl('child',true));return show('intro');
    case 'station-role': stationEntryRole=role;history.replaceState(null,'',stationRoleUrl(role));return show('intro');
    case 'station-copy-child': return copyStationChildUrl();
    case 'station-next': return nextStationFamily();
    case 'station-renew': return renewStationPair();
    case 'station-start': return stationView?.connected.child && stationView.prepared && !familyView?.ownAnswers.some(a=>a.choice) ? startBookFromCover(target) : undefined;
    case "review-start": return familySession ? edit(familySession.role,state.index) : show("intro");
    case "review-next": return reviewNext();
    case "review-choice": return chooseReviewAnswer(value);
    case "room-sound-enable":
      voiceEnabled = true;
      localStorage.setItem('siseonsai-storybook2-sound','on');
      syncVoiceControls();
      sharedRoomMotion?.sfx.unlock();
      return markNextReady();
    case "pick-review-point": {
      const { left, top, width, height } = target.getBoundingClientRect();
      if (!width || !height) return;
      return chooseReviewAnswer("other", {
        x: (event.clientX - left) / width * 100,
        y: (event.clientY - top) / height * 100,
      });
    }
    case "guided-setup":
      closePractice();
      voiceEnabled = true;
      return goToHomeSection("setup");
    case "close-practice":
      closePractice();
      return app.querySelector(`[data-practice-card="${index}"] .guide-art`).focus();
    case "practice": return openPractice(Number(index));
    case "practice-point":
    case "practice-choice": return finishPractice(event, target);
    case "guide":
      voiceEnabled ??= true;
      return goToHomeSection(action);
    case "setup": return goToHomeSection(action);
    case "listen":
      if (value) {
        voiceEnabled = true;
        localStorage.setItem('siseonsai-storybook2-sound','on');
      }
      if (value === "cover" && playingScene === "cover") return stopNarration();
      return narrate(value);
    case "type-gallery":
      stopNarration();
      filterGallery("");
      return app.querySelector("#type-gallery").showModal();
    case "gallery-filter": return filterGallery(value);
    case "toggle-voice":
      voiceEnabled = !voiceEnabled;
      localStorage.setItem('siseonsai-storybook2-sound',voiceEnabled?'on':'off');
      if (voiceEnabled) return narrate(value);
      stopNextCue();
      stopPageTurnSound();
      return stopNarration();
    case "start": return familySession ? show(familyView.bothComplete ? "report" : "ready") : show("intro");
    case "demo": leaveStationView(); return openExample();
    case "reset": clearTimeout(familyPoll);familySession=null;familyView=null;return reset(false);
    case "adult": return edit("adult");
    case "edit": return edit(role);
    case "jump": return familyBusy || Number(index)>state.index ? undefined : edit(state.role, Number(index));
    case "back": return familyBusy ? undefined : state.index > 0 ? edit(state.role, state.index - 1) : show('home');
    case "next": return next();
    case "report": return familySession && !familyView.bothComplete && !state.demo ? show("waiting") : show("report");
    case "look-answer": return chooseLook(value);
    case "habit-answer": return chooseHabit(value, target);
    case "pick-point": return pickImage(event, target);
    case "share": return shareResult(true);
    case "copy": return shareResult(false);
    case "expression": return celebrateMascot(target);
    case "chart-view": {
      const chart = target.closest(".habit-compare");
      chart.dataset.chartView = value;
      chart.querySelectorAll("[data-action=chart-view]").forEach((button) => {
        button.setAttribute("aria-pressed", String(button === target));
      });
      return;
    }
    case "camera": return openCamera(value === "family");
    case "capture": return capturePhoto();
    case "camera-fallback": {
      const input = activeCamera?.input;
      cameraDialog.close();
      stopCamera();
      return input?.click();
    }
    case "print":
    case "save-report": return showPrintOptions();
    case "native-print": return usePrintExport(event, target, true);
    case "download-print-pdf": return usePrintExport(event, target, true);
    case "download-print-image": return usePrintExport(event, target, false);
    case "remove-photo": {
      URL.revokeObjectURL(state.familyPhoto);
      state.familyPhoto = null;
      clearPrintImage();
      target.closest(".family-photo").outerHTML = photoSlot();
      preparePrintImage(app.querySelector("#print-options"));
      return app.querySelector("[data-family-photo]").focus({ preventScroll: true });
    }
  }
});

app.addEventListener("click", (event) => {
  if (event.target.matches("[data-room], [data-family-photo]")) stopNarration();
});
app.addEventListener("close", (event) => {
  if (event.target.id === "print-options" && playingScene === "print-options") stopNarration();
}, true);
app.addEventListener("change", (event) => {
  if(state.demo && event.target.matches('[data-example-role],[data-example-code]')) {
    const role=event.target.dataset.exampleCode;
    if(role && Object.hasOwn(characters,event.target.value))state.habits[role]=[...event.target.value];
    if(event.target.hasAttribute('data-example-role'))state.role=event.target.value==='adult'?'adult':'child';
    seedReviewExample();return show('report',false);
  }
  if (event.target.matches("[data-room], [data-family-photo]")) addImage(event.target);
});
app.addEventListener("input", (event) => {
  if (event.target.name === "note") state.looks[state.role].note = event.target.value;
  if (event.target.name === 'station-code') {updateStationJoin();markNextReady();}
});
app.addEventListener('keydown',event=>{if(event.target.name==='station-code' && event.key==='Enter'){event.preventDefault();joinStation();}});
app.addEventListener('toggle',()=>queueMicrotask(markNextReady),true);

const requestedBook = new URLSearchParams(location.search);
const requestedRole = requestedBook.get('book');
const requestedStationRole=requestedBook.get('station');
const requestedStationLink=new URLSearchParams((location.hash||'').slice(1));
stationEntryRole=['child','adult'].includes(requestedStationRole)?requestedStationRole:['child','adult'].includes(requestedRole)?requestedRole:null;
if(requestedStationLink.has('pair') || requestedStationLink.has('key')) {
  openStationLink(requestedStationRole,requestedStationLink);
} else if(requestedBook.get('view') === 'room') {
  show('roomPreview',false);
} else if(requestedBook.get('view') === 'demo') {
  openExample();
  if(location.hash==='#family-choice-graph')document.fonts.ready.then(()=>requestAnimationFrame(()=>app.querySelector('#family-choice-graph')?.scrollIntoView({block:'start'})));
} else if(['child','adult'].includes(requestedRole)) {
  state.role=requestedRole;
  show('intro',false);
  if(localStorage.getItem(familyStorage(requestedRole))) restoreFamily(requestedRole);
  else familyNotice(roles[requestedRole]+'의 책을 열려면 가족 코드로 연결하거나 새 가족 책을 열어 주세요.');
} else {
  const stationRole=requestedStationRole || localStorage.getItem("siseonsai-station-role");
  if(['child','adult'].includes(requestedStationRole) && requestedBook.get('connect')==='1')show('intro',false);
  else if(["child","adult"].includes(stationRole))openStationRole(stationRole);
  else show("home",false);
}

